'use strict';
const $=id=>document.getElementById(id),labels={pending:'待联系',quoted:'已报价',reserved:'已预约'},cars={'718':'保时捷 718',x5:'宝马 X5',my:'特斯拉 Model Y',e:'奔驰 E 级',gl8:'别克 GL8','gl8-653':'别克 GL8 653','denza-d9':'腾势 D9',magotan:'大众迈腾',passat:'大众帕萨特',jetta:'大众捷达',coaster:'丰田考斯特',h7:'红旗 H7'};
let offset=0,total=0,current=null,timer=null,latest=null,knownTotal=null,notificationsEnabled=false,listVersion=0,detailVersion=0;
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=value=>value?new Date(value*1000).toLocaleString('zh-CN',{hour12:false}):'—';
async function api(path,body){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok){const e=new Error(data.error||'操作失败，请重试。');e.status=r.status;throw e}return data}
function lock(message=''){clearInterval(timer);timer=null;if($('mail-dialog').open)$('mail-dialog').close();$('mail-form').reset();listVersion++;detailVersion++;current=null;knownTotal=null;latest=null;$('workspace').hidden=true;$('logout').hidden=true;$('login-panel').hidden=false;$('list').replaceChildren();$('detail').replaceChildren();$('identity').textContent='';$('login-result').textContent=message}
async function enter(){try{const d=await api('/api/operator/me');$('identity').textContent='管理员 · '+d.user.email;$('login-panel').hidden=true;$('workspace').hidden=false;$('logout').hidden=false;await loadList();await checkNotifications();clearInterval(timer);timer=setInterval(()=>{if(!document.hidden)checkNotifications()},20000)}catch(e){lock(e.status===401?'':e.message)}}
async function loadList(){const version=++listVersion;try{const form=$('filters'),query=new URLSearchParams({offset:String(offset),q:form.elements.q.value,status:form.elements.status.value});const d=await api('/api/operator/inquiries?'+query);if(version!==listVersion)return;total=d.total;$('result').textContent='找到 '+total+' 条需求';$('result').className='';let all=0;for(const key of Object.keys(labels)){const count=d.counts[key]||0;all+=count;$('count-'+key).textContent=count}$('count-all').textContent=all;$('list').innerHTML=d.inquiries.length?d.inquiries.map(v=>`<button class="request ${current?.id===v.id?'active':''}" data-id="${escape(v.id)}"><div class="request-top"><strong>${v.unread?'<i class="unread" aria-label="未读"></i>':''}${escape(v.name)}</strong><span class="badge">${labels[v.status]||labels.pending}</span></div><p>${escape(v.service)} · ${escape(cars[v.car]||'待推荐车型')}</p><p>${escape(v.city)} · ${escape(v.startDate)} → ${escape(v.endDate)}</p><p>${escape(v.people)} 人 · ${escape(v.bags)} 件行李</p><p>${date(v.created)} · ${escape(v.id)}</p></button>`).join(''):'<div class="empty">暂无符合条件的需求。</div>';$('prev').disabled=offset===0;$('next').disabled=offset+50>=total;$('page-label').textContent=total?'第 '+(offset+1)+'–'+Math.min(offset+50,total)+' 条':'0 条';$('list').querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>openDetail(b.dataset.id))}catch(e){if(e.status===401||e.status===403)lock(e.message);else{$('result').textContent=e.message;$('result').className='error'}}}
async function openDetail(id){if(current&&$('followup')&&($('followup').elements.note.value!==current.note||$('followup').elements.status.value!==current.status)&&!confirm('有尚未保存的备注，确定切换需求吗？'))return;const version=++detailVersion;try{const d=await api('/api/operator/detail?id='+encodeURIComponent(id));if(version!==detailVersion)return;current=d.inquiry;const v=current,rows=[['电话',v.phone],['微信',v.wechat],['服务',v.service],['车型',cars[v.car]||'请为我推荐'],['服务城市',v.city],['取车 / 上车',v.pickup],['还车 / 下车',v.returnAt],['目的地',v.destination],['开始',v.startAt?.replace('T',' ')],['结束',v.endAt?.replace('T',' ')],['用车天数',v.durationDays+' 天'],['人数 / 行李',v.people+' 人 / '+v.bags+' 件'],['提交时间',date(v.created)]];$('detail').innerHTML=`<p class="eyebrow">ENQUIRY DETAIL</p><h2>${escape(v.name)}</h2><p class="muted small">${escape(v.id)}</p><dl>${rows.map(([k,val])=>`<dt>${escape(k)}</dt><dd>${escape(val||'—')}</dd>`).join('')}</dl><form id="followup"><label>跟进状态<select name="status">${Object.entries(labels).map(([key,label])=>`<option value="${key}" ${key===v.status?'selected':''}>${label}</option>`).join('')}</select></label><label>跟进备注<textarea name="note" maxlength="2000" placeholder="记录联系结果、报价情况和待办事项">${escape(v.note)}</textarea></label><p class="muted small">备注仅管理员可见。状态记录不自动发送报价、锁车或收款。</p><button type="submit" class="primary">保存跟进</button><p id="save-result" role="status"></p></form><h3>跟进记录</h3>${d.history.length?d.history.map(h=>`<div class="history"><span class="badge">${labels[h.status]}</span><span class="muted small"> ${date(h.created)}</span><p>${escape(h.note||'无备注')}</p></div>`).join(''):'<p class="muted">尚无跟进记录。</p>'}`;$('followup').onsubmit=saveFollowup;await api('/api/operator/seen',{id});await loadList();await checkNotifications();if(window.innerWidth<850)$('detail').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){if(e.status===401||e.status===403)lock(e.message);else{$('result').textContent=e.message;$('result').className='error'}}}
async function saveFollowup(e){e.preventDefault();const form=e.target,button=form.querySelector('button'),record=current;button.disabled=true;try{const data=await api('/api/operator/update',{id:record.id,status:form.elements.status.value,note:form.elements.note.value,revision:record.revision});record.revision=data.revision;record.note=form.elements.note.value.trim();form.elements.note.value=record.note;record.status=form.elements.status.value;await openDetail(record.id);$('save-result').textContent='已保存';$('save-result').className='success'}catch(err){if(err.status===401||err.status===403)lock(err.message);else{$('save-result').textContent=err.message;$('save-result').className='error'}}finally{button.disabled=false}}
async function checkNotifications(){try{const d=await api('/api/operator/notifications');if(knownTotal!==null&&d.total>knownTotal){if(notificationsEnabled&&'Notification'in window&&Notification.permission==='granted'){try{new Notification('YC 有新的用车需求',{body:'请登录管理后台查看并联系客户。'})}catch{}}await loadList()}latest=d.latestId;knownTotal=d.total;$('email-status').textContent=d.email?.configured?'邮件提醒：'+d.email.pending+' 封待发送，'+d.email.sent+' 封已提交邮件服务。':'邮件提醒尚未配置 SMTP 授权码；需求会保存在后台，通知留在发送队列。';$('notice').textContent=d.unread?'你有 '+d.unread+' 条未读需求，打开需求详情即可标记已读。':'需求已读完，新的提交会在这里提醒。'}catch(e){if(e.status===401||e.status===403)lock(e.message);else $('notice').textContent='新需求检查暂时失败，请刷新重试。'}}
$('login-form').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button');b.disabled=true;$('login-result').textContent='';try{await api('/api/auth/login',{email:form.elements.email.value,password:form.elements.password.value});form.elements.password.value='';await enter()}catch(err){$('login-result').textContent=err.message}finally{b.disabled=false}};
$('logout').onclick=async()=>{try{await api('/api/auth/logout',{});lock('已退出登录。')}catch(e){$('result').textContent=e.message}};
$('filters').onsubmit=e=>{e.preventDefault();offset=0;loadList()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{$('filters').elements.status.value=b.dataset.filter;offset=0;loadList()});$('prev').onclick=()=>{offset=Math.max(0,offset-50);loadList()};$('next').onclick=()=>{offset+=50;loadList()};$('refresh').onclick=async()=>{await loadList();await checkNotifications()};
$('enable-notifications').onclick=async()=>{if(!('Notification'in window)){$('notice').textContent='此浏览器不支持系统通知，后台未读提醒仍然可用。';return}try{notificationsEnabled=(await Notification.requestPermission())==='granted';$('enable-notifications').textContent=notificationsEnabled?'浏览器提醒已启用':'浏览器提醒未授权'}catch{$('notice').textContent='无法启用浏览器提醒，后台未读提醒仍然可用。'}};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('workspace').hidden)checkNotifications()});window.addEventListener('beforeunload',e=>{if(current&&$('followup')&&($('followup').elements.note.value!==current.note||$('followup').elements.status.value!==current.status)){e.preventDefault();e.returnValue=''}});enter();

$('show-password').onclick=()=>{const input=$('login-form').elements.password,visible=input.type==='password';input.type=visible?'text':'password';$('show-password').textContent=visible?'隐藏密码':'显示密码';$('show-password').setAttribute('aria-pressed',String(visible))};

$('mail-settings').onclick=()=>{$('mail-result').textContent='';$('mail-dialog').showModal()};$('close-mail').onclick=()=>{$('mail-dialog').close();$('mail-form').reset()};
$('mail-form').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button[type="submit"]');b.disabled=true;try{const data=await api('/api/operator/mail-config',{authorizationCode:form.elements.authorizationCode.value.trim(),sendTest:form.elements.sendTest.checked});form.reset();$('mail-result').textContent=data.testQueued?'配置已保存，测试提醒已进入发送队列。请检查收件箱和垃圾邮件。':'配置已保存，新需求将进入邮件发送队列。';await checkNotifications()}catch(err){if(err.status===401||err.status===403)lock(err.message);else $('mail-result').textContent=err.message}finally{b.disabled=false}};

window.addEventListener('pageshow',event=>{if(event.persisted){lock();enter()}});
